from story_blueprints import entry as E

SOLO={
'chengdu_plain':[
E('锦城夜市的灯钱','锦江边的夜市连续开了几晚，织户周氏第一次把自家的细绣卖给了远来的客人。回家时，她却发现巡夜人正挨铺收取灯钱，数额比白日的摊税还高。\n\n巡夜人说，新市场使他们不得不添人守更；坊长拿出旧规，要求商人各自承担。若府署出钱维持灯火，夜市便能继续开放，但旧有行会也会失去决定谁能摆摊的权利。周氏已交了一笔钱，仍不知道明晚能否再来。','以公款付更钱，开放摊位。|允许坊长收钱，限明收费。|让织户与商人共同安排夜市。','commerce','BAB'),
E('府学借出的孤本','成都府学的一部旧书被抄书人借到锦坊，回来时少了几页。掌书者指责坊中工匠不知珍惜，年轻绣工却说缺页记着几种从未见过的染色法，大家只是想抄下它们。\n\n有人提议把书锁回库中，也有人愿出纸墨钱补抄。府学的名望需要维护，实用技法也值得流传。原来借书的抄手已在门外等候三日，他怕被逐出府学，却不肯承认工匠的求知有错。','资助补抄，让工匠继续借阅。|公开追责，重申府学藏书规矩。|把染色页另印成工匠小册。','literature','BAB'),
E('汉州田边的白鹭','汉州渠吏准备清理田边杂草，几名农户却拦住了役夫。他们说白鹭每年在这里繁殖，平日还能捉走稻田里的虫子。领役者只看见一段不整齐的渠岸，担心上官责怪工期。\n\n农户愿自行清出水口，留下靠田的一片草地；府学医者也想辨认鸟类与虫害的关系。若按旧图一并铲除，渠道会更容易巡视，却会让乡民觉得官府只认图纸上的笔画。','让农户保留草地，承担水口维护。|请医者观察，再调整清渠办法。|按图清渠，以粮钱补偿农户。','ecology','BAE'),
E('绵竹酒坊的清曲','绵竹酒坊试出一种香气清淡的新曲，坊主却没有把配方告诉自己的长工。长工阿祺攒钱办酒席，请师父收他为徒，得到的答复仍是：这项技法只传亲族。\n\n邻近酒户愿凑钱让府署主持试酿，也有人主张保护一家人的秘方。若把技法公开，更多酒坊能受益；若由府署指定作坊供货，则能换来较稳的礼酒，却会压缩小酒户的生计。','资助公开试酿，不按亲族择徒。|指定礼酒坊，保护其配方。|准长工另办作坊，以成酒评高下。','craft','BAE'),
E('彭州山门的药篓','彭州山民背着药篓来到城门，却被认作私取官山木料。老采药人掏出一张字迹模糊的旧凭证，守门者仍要扣下整篓草药。他的女儿正等着这笔钱购粮。\n\n医者请求把采药与伐木分开登记，山门官则担心人人以药材为借口进入禁山。我们可以重订采办凭证，维持严禁，也可以请山民与医者共同监督。无论采用哪种办法，这一家人的旧凭证都须有一个明确的处置。','补发采药凭证，退还药篓。|维持禁山，按府医所需采办。|由山民与医者共同查验药材。','medicine','BAF'),
E('唐昌田里的水碓','彭州匠人把磨粮水碓改得更省力，乡民争着把谷物送来，原来替人舂米的几户却突然少了收入。匠人说旧活计迟早要改变，村长却要求我们先想好这些人如何过冬。\n\n府署可出钱教他们修理水碓，也可按旧户保留一部分舂米名额。商人提出包下水碓，换取几年独家磨粮。机器旁已经排起长队，领头的妇人只希望今天能把米带回去。','教旧舂米户维护水碓。|保留旧户份额，限制使用。|让商人出资扩建，限定承包年限。','craft','BAF'),
E('邛州窑口的颜色','邛州窑工在一批坏坯上烧出新的釉色，师父却要求把这些器物打碎，免得毁掉作坊的声誉。小徒把其中一只藏在草棚，过路商人见后愿出高价订购。\n\n如今窑主想拿回配方，徒弟希望以自己的名字试烧，府署也收到将新器用作礼物的建议。试验会耗去柴薪和好泥，单凭一次烧成还不能保证下一批成色。我们得决定谁来承担这些风险。','资助徒弟试烧，记录失败的配方。|让窑主主持，优先制作礼器。|准商人预订，由买卖双方担风险。','craft','BAJ'),
E('临邛客栈的女账房','邛州一间客栈的女账房把多年欠账整理清楚，查出几名富商重复抵押同一批货。商人们称她无权作证，还找来亲族要求掌柜将她辞退。\n\n掌柜带来完整账册，愿让府署逐笔核验。若认可她的记录，小商户会多一种保护自己的办法；若只接受有家族担保的人作证，旧秩序容易维持，但几笔重押也可能就此蒙混过去。女账房已把原件分成两份存放。','依账册查验，认可她的证词。|按旧担保处理，维护商族体面。|设共同账房，让不同商户交叉查验。','justice','BAJ'),
E('蒲江茶园的旧坟','蒲江茶户在开垦荒坡时挖到几处旧坟，附近家族声称整片茶园都是祖茔的一部分。茶户已付过地钱，搬走便会失去几年劳作。\n\n族老愿接受一笔祭祀费用，却不肯承认茶户今后的土地权利。府署可以核实墓界，也可以划出别处土地，或让双方订下共有之约。茶户留下的地契没有画出界线，这正是当初交易最省事、如今却最棘手的地方。','另给茶户土地，保留墓界。|查验地契，重定祖茔范围。|订立共用契纸，以茶利供祭。','land','BAJ'),
E('眉州旧宅的诗稿','眉州书生在一处旧宅找到几页诗稿，宅主却想把它们卖给远来的收藏者。当地读书人请求府署买下原件，既为本地文脉留存，也让穷学生能有所借阅。\n\n宅主提醒我们，屋顶已经漏了多年，任何买书者都没有问过住户的日子。府署可以连同修屋出资，也可制作副本，或借收藏者的钱兴办一次公开讲读。保住纸页和照顾住户，应当一并考虑。','出钱修屋并留存诗稿。|刊印副本，让原件依约出售。|请收藏者资助讲读，维护旧宅声名。','literature','BAL'),
E('青神竹纸的销路','青神纸户用细竹制出的纸张卖不出去，驿署宁愿从熟识的商人手中采购。纸户的小女儿把一包样纸带进府城，请书记试写，字迹却让围观者颇为满意。\n\n旧供货商强调多年守约的功劳，纸户则请求一次公开比价。若府署转向新纸，旧商人会失去收入；若继续沿用旧合同，地方纸坊便难以承担扩大采办的费用。','公开试纸，给新纸户一份订单。|保留旧合同，要求商人采购本地纸。|把采购交给府学按用途评比。','commerce','BAL'),
E('春社的戏台','成都平原的春社搭起戏台，一位说唱人把收税吏的口音学得惟妙惟肖。乡民笑得热闹，税吏却要求停演，称这会让百姓轻视官府。\n\n社首愿删去相关段子，也希望府署不要因此撤掉整场春社。商人已付钱订了台前席位，穷户则只挤在台后听声。我们处理这桩小事的方式，会让人知道哪些笑话能说，哪些人能在共同的节日里占一席。','准其演完，免收穷户席钱。|停止讥评官吏，保留春社。|重订台费，让商人资助公共席位。','festival','BAB BAE BAF'),
E('府医的两张药方','平原几村的发热病人越来越多，府医拿出新药方，乡医则继续使用祖传的煎剂。一个失去儿子的父亲来到堂下，要求他们说清楚两种药为何不同。\n\n府医愿记录每位病人的病程，却需要纸笔与助手；乡医担心这会被用来追究自己。我们可以资助共同查验，也可以指定一种办法，或先把钱用于病家最缺的清水和粮食。','出钱记录病程，让两方共同诊治。|按府医药方办，明确诊治责任。|先给病家清水口粮，保留乡医。','medicine','BAB BAE BAL'),
],
'southern_salt_wine':[
E('嘉定寺门的石工','嘉定寺门整修的石工已经数月没有领到工钱，主持却仍要求添刻一排精美浮雕。石工许伯把最后一只凿子放到府衙门前，称自己愿放弃雕饰，只求领回应得的银钱。\n\n寺院提醒我们，这座山门会吸引远来的香客；附近村民则只看见被抽走的壮丁。府署可为工钱垫款，也可缩减雕饰，或借香客捐钱完成工程。不同做法将让山门留下不同的纪念。','先付石工工钱，缩减雕饰。|保全山门工程，由寺院筹款。|准工匠署名，以新雕饰招徕来客。','faith','BAO'),
E('峨眉山下的柴路','峨眉山下寺院封住一条旧柴路，称香火既盛，山林应当专供寺中使用。采柴妇人每天不得不多绕一座山，孩子们也跟着离开了田边。\n\n寺院愿施粥，却不愿重新开放柴路。山民请求划出明确的采柴区域，府署也可另给木料，或把入山权统一发给有担保的住户。这条路看似不起眼，却决定着许多家庭每天能余下多少时间。','恢复村民通行，限定采柴范围。|供寺院木料，换取开放旧路。|由寺院管理，保证定期施粥。','ecology','BAO'),
E('富顺井绳的赔钱','富顺井绳突然断裂，一名井工落入井中。井主认为是工人换班时操作不当，工人的弟弟却拿出早已磨损的绳头，称大家曾多次要求更换。\n\n盐商等着提货，停井查验会打乱几笔交割；若立即复工，家属可能再也得不到答复。府署需要决定赔钱与查验怎样进行，也须向其他井户说明，同样的事故今后该由谁承担。','先赔付家属，停井验绳。|由府署查验，井主承担更换。|准其复工，以盐利定期供养家属。','labor','BAP'),
E('叙州酒宴的空座','叙州商人设宴款待船主，邀请了许多熟识的贵族，却给为酒坊酿酒多年的老师傅留了一个门外座位。老师傅起身离去，其他灶户也不再供酒。\n\n宴主请府署出面恢复供应，声称礼数不可随意改变。船主只希望下一批盐酒能按约上船。我们可以让工匠入席，也可另给赏钱，或把交割从这场宴会中分开，按明白的契约处理。','让酿酒师傅入席，重新开宴。|按旧礼设席，补给工匠赏钱。|按契纸交货，不再借宴席定商价。','festival','BAP'),
E('宜宾江口的转秤','宜宾江口的盐包过了两道秤，重量竟差了许多。搬运夫陈二发现一处秤砣内填了轻木，却被商人的护卫拦住，不准继续拆验。\n\n掌秤者说，这种差额已经算进旧年的运费。若府署公开查验，几笔长期合同都可能重算；若只在今后更换新秤，过去受损的井户便拿不到补偿。陈二的搬运名额，也取决于哪一方还能容忍他的指认。','逐笔核验，保护搬运夫的名额。|更换官秤，重算本季契价。|与盐商议定补偿，避免重翻旧账。','justice','BAP'),
E('泸州城外的火窖','泸州酒窖失火，主人指责附近住户不肯帮忙扑救。住户却说，酒窖的看守从来不许他们经过井边，起火时也没有水可取。\n\n坊主愿重建酒窖，要求府署征调民夫；乡老请求先开放取水。商人已订好下一季的酒货，重建迟延会损害本府收入。我们需要把防火与采办安排在一起，而不是等下次火起再为责任争吵。','修共用水井，由坊户出钱重建。|资助防火改造，训练酒窖看守。|征役赶建，先兑现酒货订单。','craft','BAQ'),
E('合江船上的歌','合江船工编出一支新歌，唱到船主克扣饭钱时，岸边的人纷纷跟唱。船主要求官府禁唱，并称船工已经用饭钱预支过衣料。\n\n老船工带来几季的清单，愿当众说清每一笔借款。若府署查账，会触怒掌握船位的人；若只是禁止歌谣，也无法解决船上长期积累的争执。码头的下一班船已经催着他们离岸。','准船工申诉，核对饭钱清单。|禁去人身讥评，由府署重定船规。|让船帮公开账目，以船费结清旧借。','labor','BAQ'),
E('长宁竹海的租界','长宁竹户发现几片原供全村取用的竹林已被记入豪族租册。族中管事愿让他们继续砍竹，只须按担收钱。一个年轻竹匠因此不得不把刚做好的篮子全部卖掉缴租。\n\n旧乡约与新租册都盖着地方的印记。府署可重新核定公用竹林，也可承认租册并给竹户减税，或以作坊采购补贴他们。我们不能让两份彼此矛盾的文书继续同时生效。','核定公用竹林，退还本季租钱。|承认租册，为竹户另减赋税。|以作坊订单换取平价竹料。','land','BAW'),
E('荣县小井的官价','荣县小井的出卤不如大井稳定，灶户请求按小批盐货交税，掌盐者却仍按满灶估量。一个井户为了交足官盐，买回了原本由自己售出的盐包。\n\n若按实际产量核税，府库将少收一笔钱；若维持定额，一些小井可能彻底停煎。大盐商愿把这些井包下来，只要求长期的交割权。我们如何处理小井，会改变盐场今后由多少家人经营。','按实产征税，给小井宽限。|维持定额，资助井户修灶。|准盐商承包，限定收购条件。','tax','BAW'),
E('嘉州桥头的施粥','嘉州桥头的寺院连续施粥，附近酒商却抱怨雇来的搬运夫不再愿意接受低饭钱。主持说，人在饥饿时允下的工钱，不能算作公允。\n\n粮商愿捐米，条件是在粥棚前挂出自家名号。府署可以共同供养粥棚，也可劝寺院缩减施粥，或让商人负责采办。一个带着两个孩子的寡妇已来领过三次粥，她不希望自己的去处取决于商人争夺名声。','共同供养粥棚，不限制领粥者做工。|由寺院主持，劝各方维持旧工价。|让商人采办，公开每季出粮数。','food','BAO'),
E('夜里多开的一口灶','盐场为赶交货，在夜间多开了一口灶。灶火照亮了工人的住处，也使轮休的人整夜不能入睡。掌事者称订单只剩十日，过后自会恢复旧班。\n\n工人已经听过相同的承诺，要求立刻减少夜煎；盐商则威胁扣掉迟交的货款。府署可以为延期担保，也可强令继续赶工，或替灶户购买更省工的器具。眼前的一批盐，正与下一季仍能劳动的人手相互争用。','给延期担保，让灶户轮休。|按约赶交，给出明确的夜班钱。|资助改造器具，减少轮班人手。','labor','BAP BAW'),
E('盐引背面的字','叙州账房在旧盐引背面发现几行细字，写着转押时加收的利息。持券的寡妇说，丈夫生前只告诉她这是能够换回盐货的凭证。\n\n债主认为她既继承了凭证，也应当承担全部条款。府署可以核查这些细字何时添上，也可要求担保家族偿付，或承认券据并给她延期。我们需要保护交割的信用，同时让持券者知道自己究竟允诺过什么。','核验增添的条款，停止无据追偿。|承认券据，要求家族履行担保。|安排分期交割，公开转押费用。','justice','BAP BAO'),
E('酒坊留给学徒的席位','川南几家酒坊准备合办祭师宴，却只准掌柜入席。年轻学徒想把自己试酿的新酒带来，师父担心他们尚不懂得行会礼数。\n\n一位没有儿子的老掌柜愿收徒，却要求府署承认外姓学徒也能继承作坊。贵族中的出资人反对，称坊产应当继续留在熟悉的家族手中。宴席上的一张座位，如今牵涉到了多年劳作之后谁能接掌炉火。','认可学徒继承，准他们献酒。|保护坊主亲族，另给学徒工钱。|设公开试酿，让技艺决定名额。','craft','BAP BAQ BAW'),
],
'eastern_river':[
E('大足石壁上的姓名','大足石工在造像旁刻下自己的名字，出资家族却要求磨去，称只有供养者的名号应当留下。石工的儿子拿出父亲多年留下的凿痕，请我们允许后人知道是谁完成了这面石壁。\n\n寺院担心争执影响后续供养，书生则认为工匠的技法同样值得记载。府署可以保护署名，也可另立一块名册，或按供养家族的意思处置。留下什么名字，也会决定下一批工匠愿以怎样的条件来此。','保留石工姓名，资助技法记录。|尊重供养者，另给工匠赏钱。|分立供养与工匠两份名册。','faith','BAX'),
E('重庆城梯上的担夫','重庆担夫在长梯上摔坏一坛货酒，货主要求他偿付全部价钱。守梯人却说，石阶上的破损已报修多次，府署迟迟没有拨款。\n\n担夫的同伴停下搬运，要求先修路，几家商铺因此无法补货。官吏可以追回维修账款，也可让货主共同出资，或先恢复搬运再从新税中筹钱。受伤的人仍坐在梯下，等待我们决定他的欠账该如何计算。','先修石阶，免去担夫赔款。|由商铺共担维修，明确搬运责任。|恢复货运，以临时税补修城梯。','labor','BAZ'),
E('两江会流的鱼网','重庆渔户在两江会流处放下细网，几日便捕到许多小鱼。老渔民担心来年无鱼可捕，鱼商却称城中买家已经预付货钱。\n\n禁用细网会减少今季收入，也可能让穷渔户失去偿还预支的机会。府署可以给他们换网，也可划出禁捕时段，或依照旧约允许本季捕完。城中宴席的鱼价，正与江上住户下一年的生计联系在一起。','给渔户换网，宽限预支。|规定禁捕时段，公开鱼汛记录。|兑现本季鱼货，再改捕捞规矩。','ecology','BAZ'),
E('涪州渡口的婚礼','涪州一对新人过渡时被要求分别按两岸的规矩缴钱，新娘的亲族因此在船上争吵。船夫说，自己也得向两处守岸人交费，不能独自免去。\n\n几家商户愿为共同渡约出钱，只求今后不再重复收费。两岸家族却担心旧有礼仪因此失去效力。府署可从这桩婚事开始重订渡规，也可只给新人免钱，或由守军统一经营渡船。','免去重复收费，重订共同渡约。|保留两岸礼仪，由府库付钱。|交守军办渡，统一票价。','justice','BBB'),
E('武隆山中的蜂蜜','武隆山民把野蜂蜜送到府城，买家称有些蜜味混杂，只肯按最低价收购。采蜜人说，不同山花本就会酿出不同味道，若只收一种，他便须多走几日险路。\n\n府医愿辨识不同蜜源，商人则希望统一货色便于转售。我们可以资助分类，也可确认一种官价，或准山民在市中直接交易。采蜜人的手臂还留着蜂蜇，他不愿自己的劳作只换来一句货色不纯。','让山民直接交易，准许分价。|请府医辨蜜，记录山花与货色。|统一官价，由商人承担转售。','craft','BBB'),
E('合州铁匠的练炉','合州铁匠试用新炉，却需要比旧法更多的木炭。附近村民反对继续砍山，军府又在催要一批器械。炉边的学徒已经学会调火，不愿再回到效率较低的旧炉。\n\n府署可以给铁匠寻找新炭源，也可限制试炉，或让军府为专用炉承担材料。技法的收益与供养它的人手不在同一处，若只看出炉的铁器，山中的代价便会落在没人询问的住户身上。','资助节炭试炉，补给村民木料。|限制新炉，先保护山中采办。|由军府出料，优先供应器械。','craft','BBC'),
E('夔州峡口的旧棺','夔州山民在崖缝中发现一具旧棺，船主想把它带到码头供宾客观看。村寨长者坚持棺中遗骨应当留在原处，府学师生则请求制作图录。\n\n搬运需要凿开部分石壁，留下它又会使行商失去一项招徕来客的生意。我们可以只让师生记录，也可与村寨议定参观，或由府署收存遗物。谁能解释旧人的生活，不该仅由出价最高的人决定。','留下遗骨，付钱请村寨带路。|制作图录，限制取走原物。|收存棺中遗物，以展览资助码头。','archaeology','BBE'),
E('云阳江边的木排','云阳商人扎起一列木排准备顺江运走，村民却发现其中用了几根原定修桥的长木。木商称自己按价付过钱，供桥的乡老则说那笔交易没有得到村中同意。\n\n若把木排拆开，商人会误了交货；若任其离岸，修桥便要再等一季。府署可安排换木，也可重定采办责任，或先让木排起行，从货利中收钱补桥。几方争执时，江水已经开始上涨。','扣下修桥木料，补偿误期。|重核采办，由木商另供长木。|让木排起行，按货利筹修桥钱。','land','BBE'),
E('酉阳山市的两种话','酉阳山市的一笔交换因翻译争执而中止，买家以为自己已经付清，卖家却说还有一匹布没有交。兼做翻译的年轻人属于其中一个村寨，另一方不肯相信他的说法。\n\n府署可派书记学习当地语言，也可要求交易一律按府城契纸办理，或让不同村寨共同挑选翻译。商货不多，这一次处理却会影响下次赶市的人是否还愿意带货下山。','共同训练翻译，认可两种记录。|用府城契纸办理，明确担保。|由各寨轮派翻译，公开交割。','caravan','BBF'),
E('丰都庙前的诉状','丰都庙会的一出戏把冤屈带到阴司审理，戏散后，一位妇人照着戏里的格式写了诉状。书记笑她用错称呼，拒绝把纸呈上去。\n\n庙中讲者认为，戏能让不识字的人明白公道；官吏担心百姓拿鬼神故事替代府署规矩。我们可以让书记帮助改写，也可禁止借戏说讼，或让庙会公开教授正当申诉的格式。妇人只想知道自己的事能不能得到听取。','让书记改写诉状，照常受理。|限制借戏说讼，维护官署体面。|准庙会教授申诉，明列官署规矩。','justice','BBH'),
E('忠州果园的新枝','忠州果农把邻地带来的枝条接在旧树上，第一季结出较好的果子。旧园主却要求将这种枝条只用于自家的贡果，称外来技法应当由有地位的人主持。\n\n果农愿让乡民学习接枝，也怕失去依靠园主维持的地租宽限。府署可以资助公开传习，设立试验园，或承认贡果园的优先权。枝条很小，围绕它的安排却会决定技艺今后走进多少片果园。','让果农公开传习，保障租地。|设小型试验园，记录成活情况。|优先供应贡果，奖励园主推广。','agriculture','BBH'),
E('河灯照着的渡口','川东几村在江上放河灯祭奠亡者，灯船却堵住了晚到的商船。船主要求把祭礼移到别处，家属说自己的亲人正是在这个渡口失踪。\n\n乡老愿缩短仪式，商人也可等一夜，但谁都不肯先退。府署可以资助岸边祭礼，规定共用时段，或优先保证货运。一个孩子把灯又捡回了岸上，问母亲是否连这盏灯也得为城里的订单让路。','另修岸边祭台，给商船安排行期。|规定祭礼时段，保留渡口共用。|优先货运，按旧礼另给祭钱。','festival','BAZ BBB BBE BBH'),
E('码头收下的外乡徒弟','川东船场收下几名外乡徒弟，本地船匠担心工价因此下降，要求每家船场限制名额。一个擅长补板的新徒却刚修好本地师傅放弃的一艘旧船。\n\n船主希望留下新手，行会坚持先照顾旧户。我们可以用资助传习增加活计，也可保留旧户名额，或按修船质量发牌。允许怎样的人接近船架，将影响江上能够维持多少只船。','资助共同传习，不按籍贯限徒。|保护旧户名额，为新徒另找活计。|以修船试验发牌，由船主担保。','education','BAX BAZ BBB'),
],
}

SOLO['northern_shudao']=[
E('阆中城门的更鼓','阆中更鼓换了主持者，新鼓手照着府城的时刻敲鼓，住在江岸的工匠却仍按旧更开工。一批迟到的货物因此被守门者拦下，商人将责任推给没有及时听鼓的担夫。\n\n老鼓手愿教新人辨认江雾中的回声，府署也可以统一时刻，或准不同坊市保留自己的开闭安排。鼓声原本帮助人们安排生活，如今却有人借它决定谁能进城做买卖。','付酬请老鼓手传习，给担夫宽限。|统一更刻，重订城门规则。|让各坊共议时刻，公开关门例外。','astronomy','BBI'),
E('保宁药铺的借书人','保宁药铺的学徒借来一本医书，掌柜却只允许他照抄方名，不准询问病因。学徒私下记下几位病人的症状，发现同名药方并非总能起效。\n\n府医愿听取他的记录，药铺行会担心这会损害熟悉的处方。若公开比较，病家可能受益，掌柜却会失去一些权威；若封存记录，学徒以后也不会再把自己的观察带到官署。','请府医核对病程，保留学徒记录。|维护药铺行规，私下调整处方。|设共同诊治日，准病家陈述。','medicine','BBI'),
E('巴州雨夜的灯油','巴州驿夫在雨夜送信，灯油却在半路耗尽。回到驿站后，他被指责误了行期，油簿上又写着足额支领。驿夫带来空油瓶，要求当面核对。\n\n掌站者称油价上涨，只能按旧额凑数；商人愿供油，但要求免去下一次关费。府署可补足采购，也可追究掌站者，或以商路通行交换灯油。驿夫的工钱，不能继续代替没人愿意公开的差额。','补足灯油，退还驿夫扣钱。|逐笔查账，整顿驿站。|与商人订供油约，限定免关次数。','justice','BBJ'),
E('通江山里的木活字','通江书坊用木片刻出可重复排版的字，寺院希望先印经文，驿署则催印关券。刻字者说，少数常用字已经磨损，继续赶印会使整套木字报废。\n\n我们可以资助添刻，指定优先用途，或准书坊自己接单。若只按官署所需抽取人手，书坊便没有余力改进；若完全交给市价决定，贫村仍难得到足够的纸券与读本。','资助添刻，保留公共读本份额。|先供经文与关券，保证官署需要。|准书坊接单，以货利补刻新字。','literature','BBJ'),
E('广元江岸的纤路','广元纤夫发现江岸一段旧路被圈成私地，领地管事要求他们绕行山坡。搬运一船粮食因此多耗了两天，船主却不愿增加纤钱。\n\n管事提出，只要商船逐次缴钱便可重新通行。府署可以确认共用纤路，也可向领主租地，或另修道路。纤夫已经把肩上的血痕展示给书记，他们要争取的只是过去一直能走的一段岸边。','确认共用纤路，禁止逐船收费。|租下岸地，保留领主权益。|另修便道，让商船共同出资。','land','BBL'),
E('昭化驿馆的木地图','昭化驿吏在木板上刻出山道，来客可以摸着刻痕辨认分岔。府城画师认为这种地图粗陋，建议换成装裱精美的纸图。\n\n一位目力衰弱的老赶马人说，自己只会用这块木板。匠人愿增刻里程，书坊也能印副本。府署可资助两者并用，也可只保留体面的图样，或把更新交给赶马人的行会。地图怎样制作，应当考虑真正走山路的人。','保留木图，付酬增刻里程。|改用府城纸图，统一山道记号。|准行会维护地图，公开错误记录。','caravan','BBL'),
E('剑门关下的葬地','剑门一名轮戍兵去世，家属请求把他葬在离关城较近的坡地。守将称那片地需要留作军用，乡民则愿给一处旧荒田。\n\n这名士兵曾替村寨修过桥，乡老希望府署承认他的劳作。我们可以给家属择地并减役，也可坚持军地用途，或设一处共同葬地。若所有答谢都止于送葬时的几句赞语，下一批轮戍者也会看见这种安排。','给家属葬地与减役。|守住军地，按军礼给予赏钱。|设共同葬地，由军民共同维护。','military','BBM'),
E('梓潼书生的路费','梓潼书生被选中前往邻府讲学，却凑不起路费。他的父亲愿卖掉农具，府学中的富户子弟则说，既无力出行便应把名额让给别人。\n\n老师请求从府库给一份旅费，掌库官担心以后人人援例。我们可以设按学业发放的助学钱，也可依旧由家族承担，或让商人资助讲学。谁能走出本府，不应只取决于家中恰好能卖掉什么。','按学业给路费，保留名额。|由家族承担，维护旧选拔规矩。|让商人资助，讲学时公开酬谢。','education','BBM'),
E('龙安山中的兽患','龙安一处牧场接连损失牲畜，牧户要求猎杀山中的猛兽。采药人却说，兽群被新开的柴路赶到了旧牧场边。\n\n猎户愿出力，只须保证赏钱；乡老请求先调整柴路和放牧区域。府署可以为牧户补偿，调查兽径，也可悬赏捕猎。牧场主人已经把围栏加高，穷牧户却连重新购置一只羊的钱也没有。','补偿穷牧户，重划柴路与牧区。|请猎户调查兽径，安排巡护。|悬赏捕猎，先恢复牧户信心。','ecology','BBN'),
E('平武矿口的水','平武矿工把废石倒入溪沟，山下村民的饮水渐渐浑浊。矿主说，另运废石会增加成本，暂时停矿又会误了军府的铁料。\n\n一个取水的孩子在溪边滑伤，家属因此要求府署立即处理。我们可以出钱修排水，也可让矿主承担改造，或先把饮水引到别处。眼前的采购压力，不能使矿口与村落之间的溪水永远无人负责。','让矿主修排水，给村民赔付。|资助新采办办法，记录水质。|另引饮水，维持军料供应。','labor','BBN'),
E('达州关外的空仓','达州商队在关外等待放行，附近仓房却因税额过高而一直空着。仓主宁愿不收货，也不愿承担货物受潮后的赔钱。\n\n关吏主张减税招货，府库却指望这笔收入支付守关。我们可以改定仓税，提供短期担保，或把仓房交给守军。一个卖粮小贩已经把粮袋拆开晾晒，他等不起关吏与仓主把旧规争论到下一季。','减仓税，准小商贩先入仓。|府库作保，维持原有税额。|交守军办仓，统筹关口补给。','commerce','BBO'),
E('顺庆的两份族谱','顺庆两家人都称自己应当主持修桥，因为旧族谱记载祖先最早捐过土地。新住户拿出最近几年的工钱清单，请求也在桥约上署名。\n\n族老坚持祖先的功劳不可重写，书记则认为桥还依靠今天的人维修。府署可以并记旧事与新出资，也可保留旧族的主持权，或把修桥完全转为公账。让人愿意继续出钱，比仅为古老的名字排序更难。','并记旧功与新出资，共议修桥。|保留旧族主持，要求公开工钱。|转入府署公账，统一修桥责任。','justice','BBP'),
E('驿路上的失物袋','蜀道驿卒拾到一袋钱，数日后两名商人都带着担保人来认领。年轻驿卒记得其中一枚钱上的缺口，却因没有家族作保而不被信任。\n\n府署可按物证查验，也可接受较有声望的担保，或让商人行会共同审理。驿卒已经把袋子原样存进关库，他担心自己守规矩的结果反而是赔上多年工钱。处理此事也会影响沿途人是否还愿意上交拾物。','依物证查验，保护驿卒。|按旧担保裁断，维持关口信用。|让行会共同核对，公布认领办法。','justice','BBI BBL BBM'),
]

SOLO['central_hills']=[
E('简州织户的春假','简州织户为赶一批布料，错过了自家田地的春耕。坊主愿预付粮钱，却要求他们在下一季继续留在机上。织妇何氏说，这样连田租也只能靠坊主垫付。\n\n乡老请求准织户暂离作坊，商人则催促按期交布。府署可以为延期担保，也可补贴雇人耕田，或承认预付合同。我们要处理的并不只是一批布，还包括工匠今后是否仍有机会依靠自己的田地生活。','准织户春耕，为延期交布担保。|资助雇人耕田，维持订单。|承认预付约，严定追加债息。','labor','BBQ'),
E('内江糖灶的新手','内江糖灶收了几名外乡学徒，本地灶工说他们不懂得掌火，要求把试煎的损失都记在学徒名下。老师傅却发现其中一个新手正好调出了更清的糖色。\n\n坊主希望留下他的办法，行会只愿给他普通搬运的工钱。府署可主持公开试煎，也可维护旧工阶，或让师傅自定传习。一个尚无积蓄的学徒，不该只在出错时才被记下名字。','按试煎成色定工钱。|维护旧工阶，给予新手赏钱。|资助共同传习，分担试煎损失。','craft','BBQ'),
E('仁寿地契上的红线','仁寿书记在新地契上画了一条笔直红线，却把旧村路也圈进了田主地界。农户每天绕行，田主则拿着新契声称自己没有违背官府。\n\n旧路没有完整图纸，只有几位老人记得过去怎样走。府署可以听取乡老并改契，也可另修村路，或以减租换取田主开放通行。书记认为这只是地图上的小误差，走路的人却得每天为它付出时间。','改契保留村路，采纳乡老见证。|另修便道，维持新契效力。|以减租换通行，写明长期责任。','land','BBQ'),
E('遂宁义仓的钥匙','遂宁义仓换了看守，旧钥匙却仍留在乡老家中。新看守要求收回，乡老说村中出过大半粮食，不能任由府署独自开仓。\n\n一名借粮的农户在两家之间往返，始终领不到当季种粮。府署可以设置共同开启的办法，也可集中保管钥匙，或将仓粮按出资分账。仓中粮食尚好，难处在于谁能批准它被用于急需。','由府署与乡里共同开仓。|统一钥匙，先发种粮。|按出资分账，明确各家粮权。','food','BBR'),
E('安岳石窟的拓片','安岳工匠制作石窟拓片，准备在邻府出售，寺院却要求每张先缴供养钱。工匠的弟子把墨纸用完后，仍未凑够第一笔收费。\n\n寺院需要修补洞窟，也担心来客损伤石面。府学请求保留研究副本，商人愿预订大批拓片。我们可以划定可拓区域，资助修护，或让寺院专营。收藏与传习都依靠石面仍能留给后来的人。','划定可拓区域，以销售分成修护。|府库出修护钱，留府学副本。|让寺院专营，限制石面使用。','archaeology','BBR'),
E('潼川春市的草席','潼川春市的草席摊突然被指定只准旧行会摆设，新住户把自己编好的席子又背回村里。行会说，名额能保护货色，商人却发现旧摊的席价已经上涨。\n\n府署可开放试售，也可维持旧行规，或设公开验货。一个刚搬来的老人没有名望作保，却能把席边编得紧实。决定谁能卖货，既影响行会的地位，也影响本府能否得到更多便宜的日用品。','准新住户试售，限明摊费。|保护旧行会，要求维持旧价。|公开验货，以质量发摊牌。','commerce','BBS'),
E('射洪书生与酒户','射洪书生请求酒户资助一部地方志，酒户愿出钱，却要求写入自家酒窖的优点。编书者的朋友说，这种赞语会使整部志书失去信用。\n\n府学没有足够纸墨，拒绝出资便可能使刊印搁置。我们可以承担部分费用，限定出资者的署名，也可准双方自己达成安排。酒户真正想得到的是体面，而书生需要留下可以被后人查验的记载。','资助刊印，明确事实与题名。|准酒户署名，保护地方声誉。|分印正文与商户附册。','literature','BBS'),
E('盐亭桑园的围墙','盐亭豪族在旧桑园外加高围墙，过去捡拾落叶的穷户因此失去一项收入。管事说，桑叶应当留给自家养蚕，不能继续任人取用。\n\n穷户愿按季付小钱，也有人请求府署开辟共用桑地。我们可以议定拾叶权，资助另种桑苗，或维护围墙与旧业主权益。养蚕需要完整的叶量，乡民的生计也不该只能等管事一时兴起。','保留按季拾叶权，订明数量。|资助共用桑地，训练养蚕户。|保护桑园，另给穷户短期工役。','agriculture','BBS'),
E('广安山村的染缸','广安村民用山草染布，染坊主却称这些颜色不合行会规矩，不许他们进城销售。一个买家穿着新染的布衣来到府衙，证明自己正是按这种颜色订货。\n\n染坊愿收村民作工，但不准他们保留自己的配方。府署可准许新布试售，也可按旧行会验色，或出钱让两种技法相互比较。市场究竟需要什么，不应只由最早取得牌照的人说了算。','准山村布户试售。|按旧行会验色，保护现有作坊。|资助比较技法，公开耐色记录。','craft','BBT'),
E('华蓥山下的炭钱','华蓥山下几户人家烧炭供铁坊，收购者却连续压价，称路上损耗比从前更多。炭户的长子决定卖掉驴，改去城中做短工。\n\n铁坊需要稳定炭源，府署可查验损耗，也可把路费从关税中减免，或让铁坊直接与炭户订约。继续只谈一担炭的市价，便会忽略维持采办所需的牲畜、道路与村中留得住的人。','减免运炭路费，保住炭户牲畜。|查验采办损耗，重核契价。|让铁坊直接订货，承担运输。','commerce','BBT'),
E('岳池农户的早种','岳池几户农人提前下种，邻人认为他们破坏了共同看水的时刻。早种者却拿出去年留下的天气记录，说这能避开一场常见的晚旱。\n\n若允许各自改期，共用水口的安排会变复杂；若强令按旧期下种，也可能失去一项有用经验。府署可以划出试验田，调整分水，或维持乡约。最先下种的农户已经欠了种钱，他无法等到来年再证明自己的判断。','调整分水，给试种户宽限。|资助试验田，逐季记录。|维持乡约，补偿改期损失。','agriculture','BBT'),
E('义仓门前的婚事','川中两家人为婚礼借粮，仓吏却发现一方去年还未还清。族老坚持婚事关系家族体面，要求照例发粮，贫户则抱怨自己的口粮申请反而要排队。\n\n府署可把婚礼与救急分开办理，也可准族老担保，或让宴席缩小规模。粮食既能保全礼数，也能救济眼前的饥饿。我们如何安排这一次，将成为下一户来借粮的人援引的例子。','先供贫户，婚礼依力减办。|准族老担保，严格订归期。|用少量公粮办共同婚礼。','festival','BBQ BBR BBS BBT'),
E('乡兵教头的田租','川中乡兵教头在操练期间欠下田租，田主扣走了他的农具。乡兵说，教头修过村墙，府署也曾夸赞，却从未给足误农的补偿。\n\n军府希望他继续训练，田主则要求保障地租。我们可以出钱补租，让村民共同供养，或减少操练次数。保留一位熟悉乡里的人，比发一份新的名册更难，也需要在平日说明军务占用了谁的劳动。','补付误农钱，保留教头。|由村户共养，按役额分摊。|缩减操练，准其回田还租。','military','BBQ BBR BBT'),
]

SOLO['western_tea_horse']=[
E('雅州茶篓上的名字','雅州茶商把收购来的茶装进统一篓袋，山村茶户原有的记号都被削去了。一个茶户在市中发现自家茶叶以另一家名号售出，索要说明时却被告知自己已经卖断。\n\n茶商认为统一货色有利于远途交易，府署也需要稳定的交割；茶户则希望保留质量好的茶能带来的名声。我们可以规定产地记号，确认卖断契约，或设公用验茶。谁的名字留在篓上，也会决定来年谁能得到更好的订单。','保留产地记号，公开验茶。|维护卖断契约，保障商队交割。|设公用验茶，让茶户与商人共同署名。','commerce','BBU'),
E('名山茶园里的客师','名山来了一位外地制茶师，提出改变杀青的火候。本地老师傅愿与他比较，却担心学徒学会新法后离开原有作坊。\n\n茶户已备好一批鲜叶，若试验失败便没有第二次采摘可用。府署可以分担试制，限定先在小批茶上比较，或依旧保护旧坊的供货。来客没有在此安家，他希望得到的既有工钱，也有能够继续授徒的身份。','分担试制，准客师留下授徒。|先小批比较，按成茶定价。|保持旧坊供货，给客师短期工钱。','craft','BBU'),
E('荥经桥头的病马','荥经桥头一匹病马突然倒下，桥户要求货主将它拖走，医马人却请求先卸下茶篓。商队说赶路要紧，若耽误一天便会误了关市。\n\n桥边一家人愿给马添草，条件是府署免去他们尚欠的一次岗役。我们可以出钱安置，也可责令商队承担，或让桥户把照料列入收费。对商队而言它是一匹可以更换的驮马，对沿路住户而言却是又一项没有写进旧约的劳作。','雇人卸货治马，补偿桥户。|让商队承担，暂停其通行。|订明照料费，允许桥户经营。','veterinary','BBU'),
E('汶川水边的织毯','汶川牧户带来新织的毯子，府城商人嫌图纹陌生，只肯按普通粗织收购。牧户的女儿说，那些纹样记录了家族迁居的路线，不愿为卖货全部拆去。\n\n府署可让图纹作为当地货色的标识，也可资助适合城中买家的新样，或仅按保暖耐用验货。交易可以改变织法，也可能让原有记忆渐渐失去讲述的场合。她把一条小毯留给了负责翻译的书记。','保留图纹，资助公开展示。|试织新样，让织户保留原有技法。|按耐用验货，准商人自行转售。','culture','BBV'),
E('茂州冬市的水井','茂州冬市的住户把水井围起，只许旧户取水。来赶市的牧人不得不去结冰的河边，已有牲畜在坡上跌伤。\n\n井主说，多来的客人使井水供应不足，愿开放取水，只须府署承担扩井。我们也可另建客井，或限制赶市的人数。水井旁的小争执，会影响牧人以后是继续来此，还是把马匹与羊毛带到别处。','扩井共用，按住户与来客分摊。|另设客井，保护旧户用水。|限制赶市名额，先照顾本地住户。','water','BBV'),
E('石泉的陌生药方','石泉府医见到一种牧人常用的草药，愿试着记录，寺中医者却担心病家因此放弃熟悉的治疗。牧人只请求不要在未经试用前把药篓全部烧掉。\n\n一个旧病反复的驿夫愿配合查验，但希望府署为休工期间的饭钱作保。我们可以支持共同诊治，也可暂禁陌生药物，或只把它用于牲畜。药方的来历与药效，并不一定能由同一种担保说明。','共同查验，补贴驿夫误工。|暂禁新药，维护现有医者信用。|先用于牲畜，积累观察记录。','medicine','BBV'),
E('松潘雪后的行期','松潘大雪封住山道，关将仍按旧日名册要求商队启程。领队提醒他，几处风口连熟悉道路的牧人也不肯带路。\n\n商人愿多付一笔护行钱，牧人却说钱不能让积雪停止崩落。府署可以重新定期，派人先查道路，或要求守军护送。一个赶马少年已经把货篓卸了下来，他不想为了账册上写下的日期失去同行的人。','改定行期，不追究迟到。|派牧人查道，付足工钱。|由守军护送，先通重要货路。','caravan','BBW'),
E('松州织毯人的学徒','松州织毯人愿收一位府城学徒，却要求他先住进牧户，了解图纹背后的旧事。学徒的担保家族认为这是失了体面，要求将传习改在城中。\n\n织毯人说，若只学几种颜色，便不算学会这门手艺。府署可认可双方约定，也可安排城中授课，或让商人只采购成品。怎样传习，将影响牧户今后是否还愿把技法带到城里，而不仅仅是一位学徒怎样生活。','认可住学安排，保护学徒。|出钱办城中传习，兼请牧户讲述。|只采购成品，保留牧户自理。','education','BBW'),
E('河曲草场的界标','松潘河曲的两处牧户各在草场上立了界标，经过的马队不知道向谁付钱。双方都搬出旧年见证人，却说不清河道改移后原界究竟在哪里。\n\n府署可按现状重定草场，也可维持原约并给受损者补偿，或划出一段共用牧地。马队的牲畜已经饿了半日，若界争拖下去，他们只会记得这个原本能够歇脚的地方如今很难通行。','划出共用牧地，补偿受损者。|按现状查界，重写牧约。|维护旧见证，由双方担保马队。','land','BBW'),
E('茶市中的婚约','茶马市中两家人为婚约争执，牧户想以马匹抵付，府城家族却坚持只收现钱。一位已经相识多年的年轻女子请求他们不要把婚事变成一场不断加价的交割。\n\n族老说，婚礼关系家族声望，不能临时改变礼数。府署可以认可不同嫁资，也可依旧按城中规矩，或安排双方共同见证。一次婚约若得到妥当处理，也会影响其他来客是否把这里看作能长期居住的地方。','认可不同嫁资，让双方自主议定。|按城中旧礼办，给予有限资助。|安排共同见证，限制追加索取。','justice','BBU BBV BBW'),
E('牧人给寺院的羊毛','牧人向山门寺院送了羊毛，主持却要求先改用寺中认可的礼数，否则不予收下。翻译者解释，这是牧户答谢受助的方式，并不表示轻慢。\n\n府署可劝寺院承认不同来历的馈赠，也可要求来客遵守统一礼规，或把羊毛用于共设的病马棚。牧人已在山门前等待许久，他想知道曾经得到的帮助是否还允许自己以熟悉的方法回报。','承认馈赠，维护不同礼俗。|按寺院礼规受领，另给牧人赏钱。|将羊毛用于共设棚舍，不附礼规。','faith','BBU BBV'),
E('边市留下的马铃','茶马市散后，驿卒拾到一只刻有家族记号的马铃，几位商人请求把它融成新铃。驿卒却记得主人是曾为我们带路的老牧人。\n\n府署可以派人寻主，存入公库，或按行会旧例让失物出售。马铃价值不高，但来此赶市的人会从处理方式看出，官府是否还记得未写进大宗契纸的小物与旧情。驿卒愿自己走一趟，只希望沿路有地方可以借宿。','给驿卒路费，送还马铃。|存入公库，按记号公告认领。|依行会旧例出售，以款补驿。','justice','BBU BBV BBW'),
E('山口的两支歌','茶路上来往的人在驿站唱起不同的歌，府城官员嫌其中一支听不懂，要求只准唱熟悉的曲调。守站人却发现，两支歌都在提醒赶马人同一处险弯。\n\n书生愿把歌词记下，行商也想请歌者在市中演唱。我们可以承认不同声音，统一军用号令，或把民间歌声留给私人宴席。听懂一支歌需要时间，沿路行人是否愿意继续开口却可能由一次禁令决定。','准两支歌流传，资助翻译记录。|只统一军用号令，保留民间歌声。|按府城曲调办官宴，另给歌者酬钱。','culture','BBU BBV BBW'),
]

SOLO['southwestern_valleys']=[
E('盐源湖边的旧船','盐源湖边渔户修好一只旧船，领地管事却要求先用来运官货。船主的父亲一直靠这只船捕鱼，若失去几日行期，家中便无法按时缴租。\n\n管事说，临时调船属于旧役额，渔户则出示了已经完役的木牌。府署可以付钱雇船，重核役额，或坚持先运官货。怎样处理旧船，会让湖边住户知道保存好自己的器具是否反而意味着承担更多征用。','付钱雇船，保留渔户行期。|核清木牌，重定调船名额。|先运官货，给渔户明确补偿。','labor','BBX'),
E('盐源盐池的水口','盐源盐池边的农户在上游修小水口，盐户认为它使卤水变淡，要求立刻拆掉。农户却说，若无水口，刚种下的田地便会干裂。\n\n老盐工愿与农户一起分季用水，掌盐者只想维持定额产盐。府署可以组织查验，也可补偿农户改种，或重新分配盐池税额。两方都依靠同一股来水，单听一种收益便很难看清另一方失去的是什么。','分季用水，补偿短期损失。|查验水势，按实产重核盐额。|优先保盐，资助农户改种。','water','BBX'),
E('德昌果园的嫁接人','德昌果园里来了一位熟悉嫁接的客人，老园主愿出钱留他，却不准他给其他果户传授。客人已经与邻村少年约好上山，因而拒绝独家雇约。\n\n府署可资助公共传习，也可保护园主的出资，或让客人自行接活。园主认为技法应当为付钱者服务，邻村果户则希望改好自己收成不稳的树。我们怎样安排传习，也会影响以后是否还有陌生工匠愿意留下。','资助公开传习，让各户参看。|保护出资园主，限定独家期限。|准客人自由接活，按结果计酬。','agriculture','BBY'),
E('会川路上的红土','会川商队沿路留下红土与碎矿，村民发现雨后井水变了颜色。运矿人认为这是山中常见的土色，拒绝支付清井的钱。\n\n府医愿查验，铁坊又担心停止运输会误工。我们可以先给村民另寻饮水，责令运矿人改用围车，或按旧路继续运货并另收修井费。一个孩子带来的水罐已经放在堂上，没有人能只凭一句惯常如此就说明它是否适合饮用。','先供清水，责令改进运输。|请府医查验，公开结果。|维持运货，收取清井费用。','medicine','BBY'),
E('黎州渡口的木契','黎州渡口几户村民拿着木契请求保留旧有免费通行，守渡者却说新纸册中没有他们的名字。村民无法说清旧契是谁刻的，只记得祖辈一直凭它过河。\n\n府署可听取沿岸见证，给予重新登记，也可只承认纸册，或改成按每年维护次数免钱。木契的真假需要核实，不能让不识官文的人因此永远无法陈述自己履行过的责任。','核实沿岸见证，补登记通行权。|维护纸册，给一次临时宽免。|按维护次数定免渡，重写共同契约。','justice','BBZ'),
E('汉源山里的梨树','汉源山民把耐寒的梨枝带到府城，园吏嫌枝条形状粗陋，不准进入官苑。一个买家却称这类梨在山路上保存得更久，愿为试种出钱。\n\n府署可设试园，准山民自行销售，或维持官苑的旧有标准。山民更关心来年能否继续带枝下山，不愿仅因一次贡果挑选便被认定货色低劣。什么样的树值得保留，也不只由枝叶是否齐整决定。','准山民销售，保护不同梨种。|设试园，比较耐寒与储运。|维护官苑标准，采购少量山梨。','agriculture','BBZ'),
E('马湖渡船上的鼓','马湖村寨过节时把鼓搬到渡船，船上来客纷纷停留，掌渡者却担心误了官货行期。击鼓者说，旧年正是在同一条船上与邻寨订下往来之约。\n\n府署可另给节船，安排共用时段，也可优先保证官货。商人希望借节日开市，却不愿承担渡船的修补。怎样安排这面鼓，将影响村寨的节日能否与新增加的商货一同留在渡口。','另给节船，准村寨共同开市。|划定共用时段，由商人付修船钱。|优先官货，按旧礼另办岸祭。','festival','BCA'),
E('雷波山寨的铁锁','雷波铁匠做出一种结实的新锁，寨主要求只给自己使用，担心普通住户也能把粮食锁起来，拒绝交出欠粮。铁匠的妹妹说，自家粮袋正需要防盗。\n\n府署可以准许普遍售锁，保护寨主的采办权，或将新锁先用于公共仓房。器物改变了谁能掌握自家财物，也使旧有借粮与追偿方式受到挑战。铁匠不希望一项改进只成为更容易扣粮的工具。','准住户购锁，按契纸处理欠粮。|保护寨主订单，限制转售。|先给公共仓房配锁，公开钥匙保管。','craft','BCA'),
E('建昌议事堂的翻译','建昌议事堂新来的书记把村寨的几个称谓都写成了同一个字。长者发现自己的承诺被混入另一寨名下，要求重新说明。\n\n书记担心改册使府署失去体面，翻译者愿逐寨核对，却需要沿路住宿与工钱。我们可以公开改正，也可另附注解，或只承认后来统一的称谓。若不分辨谁说过什么，一份看似齐整的议约便难以真正落实。','公开改册，支付逐寨核对费用。|另附旧称注解，保留统一册式。|按统一称谓执行，要求长者共同担保。','education','BCB'),
E('普格谷中的铜鼓','普格村寨准备修补铜鼓，外来收藏者却愿出高价把它买走。鼓主的家人需要这笔钱，其他住户说，共同祭礼不能由一家人独自决定。\n\n府署可资助修鼓，安排公共保管，也可承认鼓主的出售权。铜鼓既是器物，也是村寨共同使用多年的见证。怎样处置，不能只靠今天谁拥有将它抬进屋里的力气来说明。','资助修鼓，认可共同使用。|设公共保管，给鼓主家人补偿。|承认出售，另铸一面供祭礼使用。','culture','BCB'),
E('永宁谷口的宿账','永宁宿店替来往商队记下饭钱，却把不识纸字的赶马人列作无人担保的欠户。赶马人拿出雇主交给自己的木牌，称饭钱本应由货主支付。\n\n宿店怕木牌无效，商人又已离开谷口。府署可以核实木牌并替赶马人追偿，也可要求家族担保，或为沿路宿店设统一账册。一个已经完成护行的人，不应到最后才知道自己的口粮并未算在工钱里面。','核实木牌，向货主追偿。|要求担保，给予赶马人宽限。|统一宿账，写明雇工口粮责任。','justice','BCC'),
E('谷中铁坊的烟','西南谷中铁坊扩了炉火，烟尘落在邻村的晾粮处。坊主称风向难料，粮户却说以前的小炉从未造成这样大的损失。\n\n匠人提出调整炉口，但要停工几日；商人希望先赶交器械。府署可以补偿粮户并改炉，也可让村民迁移晾粮，或重订开炉时刻。扩大生产的收益在坊中，损耗却出现在另一户人的粮袋里。','改炉并补偿粮户。|资助试验炉口，分担停工。|维持订单，另给公共晾粮地。','craft','BBY BBZ BCB'),
E('诸谷相逢的婚宴','两处山谷的家人相会办婚宴，席上却为哪一种称谓先被念出而起争执。新郎的姨母提醒大家，早年的桥约本就是靠双方愿意听懂对方的话才订下来。\n\n府署可安排共同见证，按旧有等级排定礼数，也可让新人自行决定。婚宴的饭钱不多，来往的亲族却会把这一次安排记得很久。我们可以保全熟悉的体面，也可以为今后更多跨谷的家庭留下方便。','让新人决定，共同见证婚约。|按旧等级行礼，维护各寨声望。|资助双语礼文，认可不同称谓。','culture','BBX BBY BBZ BCA BCB BCC'),
]

